use super::BindParam;
use crate::error::{Result, ServiceError};
use diesel::pg::Pg;
use diesel::query_builder::{BoxedSqlQuery, SqlQuery};
use diesel::sql_types::{Array, BigInt, Bool, Date, Float8, Text, Timestamptz};
use tracing::error;

pub(crate) fn max_dollar_placeholder(sql: &str) -> usize {
    dollar_placeholder_spans(sql)
        .into_iter()
        .map(|(_, _, value)| value)
        .max()
        .unwrap_or(0)
}

/// Shift PostgreSQL `$N` bind placeholders in SQL generated by Diesel.
///
/// Quoted strings, quoted identifiers, dollar-quoted bodies, and comments are
/// skipped so literal text such as a metadata filter containing `$1` is not
/// mistaken for a bind placeholder.
pub(crate) fn shift_dollar_placeholders(sql: &str, offset: usize) -> String {
    if offset == 0 {
        return sql.to_string();
    }

    let placeholders = dollar_placeholder_spans(sql);
    let mut shifted = String::with_capacity(sql.len());
    let mut copied_through = 0usize;

    for (start, end, value) in placeholders {
        shifted.push_str(&sql[copied_through..start]);
        shifted.push('$');
        shifted.push_str(&(value + offset).to_string());
        copied_through = end;
    }

    shifted.push_str(&sql[copied_through..]);
    shifted
}

fn dollar_placeholder_spans(sql: &str) -> Vec<(usize, usize, usize)> {
    let bytes = sql.as_bytes();
    let mut placeholders = Vec::new();
    let mut i = 0usize;

    while i < bytes.len() {
        match bytes[i] {
            b'\'' => i = skip_quoted(bytes, i, b'\'', is_escape_string_prefix(bytes, i)),
            b'"' => i = skip_quoted(bytes, i, b'"', false),
            b'-' if bytes.get(i + 1) == Some(&b'-') => i = skip_line_comment(bytes, i),
            b'/' if bytes.get(i + 1) == Some(&b'*') => i = skip_block_comment(bytes, i),
            b'$' if bytes.get(i + 1).is_some_and(u8::is_ascii_digit) => {
                let start = i;
                i += 1;
                let mut value = 0usize;
                while i < bytes.len() && bytes[i].is_ascii_digit() {
                    value = value * 10 + usize::from(bytes[i] - b'0');
                    i += 1;
                }
                placeholders.push((start, i, value));
            }
            b'$' => {
                if let Some((delimiter, body_start)) = dollar_quote_delimiter(sql, i) {
                    if let Some(relative_end) = sql[body_start..].find(delimiter) {
                        i = body_start + relative_end + delimiter.len();
                    } else {
                        i += 1;
                    }
                } else {
                    i += 1;
                }
            }
            _ => i += 1,
        }
    }

    placeholders
}

fn skip_quoted(bytes: &[u8], start: usize, quote: u8, backslash_escapes: bool) -> usize {
    let mut i = start + 1;
    while i < bytes.len() {
        if bytes[i] == quote {
            if bytes.get(i + 1) == Some(&quote) {
                i += 2;
            } else {
                return i + 1;
            }
        } else if backslash_escapes && bytes[i] == b'\\' {
            i = (i + 2).min(bytes.len());
        } else {
            i += 1;
        }
    }
    bytes.len()
}

fn is_escape_string_prefix(bytes: &[u8], quote_index: usize) -> bool {
    if quote_index == 0 || !matches!(bytes[quote_index - 1], b'e' | b'E') {
        return false;
    }

    quote_index == 1
        || !matches!(
            bytes[quote_index - 2],
            b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'_' | b'$'
        )
}

fn skip_line_comment(bytes: &[u8], start: usize) -> usize {
    bytes[start..]
        .iter()
        .position(|byte| *byte == b'\n')
        .map(|offset| start + offset + 1)
        .unwrap_or(bytes.len())
}

fn skip_block_comment(bytes: &[u8], start: usize) -> usize {
    let mut depth = 1usize;
    let mut i = start + 2;
    while i + 1 < bytes.len() {
        match (bytes[i], bytes[i + 1]) {
            (b'/', b'*') => {
                depth += 1;
                i += 2;
            }
            (b'*', b'/') => {
                depth -= 1;
                i += 2;
                if depth == 0 {
                    return i;
                }
            }
            _ => i += 1,
        }
    }
    bytes.len()
}

fn dollar_quote_delimiter(sql: &str, start: usize) -> Option<(&str, usize)> {
    let bytes = sql.as_bytes();
    let mut i = start + 1;
    if bytes.get(i) == Some(&b'$') {
        return Some((&sql[start..=i], i + 1));
    }
    if !bytes
        .get(i)
        .is_some_and(|byte| byte.is_ascii_alphabetic() || *byte == b'_')
    {
        return None;
    }

    i += 1;
    while bytes
        .get(i)
        .is_some_and(|byte| byte.is_ascii_alphanumeric() || *byte == b'_')
    {
        i += 1;
    }
    (bytes.get(i) == Some(&b'$')).then(|| (&sql[start..=i], i + 1))
}

pub(crate) fn bind_sql_param<'a>(
    query: BoxedSqlQuery<'a, Pg, SqlQuery>,
    param: BindParam,
) -> Result<BoxedSqlQuery<'a, Pg, SqlQuery>> {
    match param {
        BindParam::Text(value) => Ok(query.bind::<Text, _>(value)),
        BindParam::TextArray(values) => Ok(query.bind::<Array<Text>, _>(values)),
        BindParam::IntArray(values) => Ok(query.bind::<Array<BigInt>, _>(values)),
        BindParam::Bool(value) => Ok(query.bind::<Bool, _>(value)),
        BindParam::Int(value) => Ok(query.bind::<BigInt, _>(value)),
        BindParam::Float(value) => Ok(query.bind::<Float8, _>(value)),
        BindParam::Timestamptz(value) => {
            let timestamp = chrono::DateTime::parse_from_rfc3339(&value)
                .map(|dt| dt.with_timezone(&chrono::Utc))
                .map_err(|err| {
                    ServiceError::Internal(anyhow::anyhow!(
                        "invalid timestamptz bind {value:?}: {err}"
                    ))
                })?;
            Ok(query.bind::<Timestamptz, _>(timestamp))
        }
        BindParam::Uuid(value) => Ok(query.bind::<diesel::sql_types::Uuid, _>(value)),
        BindParam::Date(value) => {
            let date = chrono::NaiveDate::parse_from_str(&value, "%Y-%m-%d").map_err(|err| {
                ServiceError::Internal(anyhow::anyhow!("invalid date bind {value:?}: {err}"))
            })?;
            Ok(query.bind::<Date, _>(date))
        }
    }
}

pub(crate) fn reconcile_limit_offset_binds(
    sql: &str,
    params: &mut Vec<BindParam>,
    limit: i64,
    offset: i64,
) -> Result<()> {
    let expected = max_dollar_placeholder(sql);
    let current = params.len();
    if expected < current {
        return Err(ServiceError::Internal(anyhow::anyhow!(
            "sql expects {expected} binds but {current} were collected"
        )));
    }

    match expected.saturating_sub(current) {
        0 => Ok(()),
        1 => {
            params.push(BindParam::Int(limit));
            Ok(())
        }
        2 => {
            params.push(BindParam::Int(limit));
            params.push(BindParam::Int(offset));
            Ok(())
        }
        extra => Err(ServiceError::Internal(anyhow::anyhow!(
            "unexpected bind arity gap: {extra}"
        ))),
    }
}

pub(crate) fn diesel_sql<T>(query: &T) -> Result<String>
where
    T: diesel::query_builder::QueryFragment<diesel::pg::Pg>,
{
    use diesel::query_builder::QueryBuilder as _;

    let backend = diesel::pg::Pg;
    let mut query_builder = <diesel::pg::Pg as diesel::backend::Backend>::QueryBuilder::default();
    diesel::query_builder::QueryFragment::<diesel::pg::Pg>::to_sql(
        query,
        &mut query_builder,
        &backend,
    )
    .map_err(|err| {
        error!(error = ?err, "failed to serialize diesel SQL");
        ServiceError::Internal(anyhow::anyhow!("failed to serialize SQL"))
    })?;

    Ok(query_builder.finish())
}

#[cfg(any(test, debug_assertions))]
pub(crate) fn diesel_bind_count<T>(query: &T) -> Result<usize>
where
    T: diesel::query_builder::QueryFragment<diesel::pg::Pg>,
{
    let rendered = diesel::debug_query::<diesel::pg::Pg, _>(query).to_string();
    let marker = "-- binds:";
    let binds = rendered
        .split_once(marker)
        .map(|(_, suffix)| suffix.trim())
        .ok_or_else(|| ServiceError::Internal(anyhow::anyhow!("missing binds marker")))?;

    count_debug_binds_list(binds).ok_or_else(|| {
        ServiceError::Internal(anyhow::anyhow!("failed to parse diesel debug bind list"))
    })
}

#[cfg(any(test, debug_assertions))]
fn count_debug_binds_list(binds: &str) -> Option<usize> {
    let bytes = binds.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() && bytes[i].is_ascii_whitespace() {
        i += 1;
    }

    if i >= bytes.len() || bytes[i] != b'[' {
        return None;
    }

    let mut bracket_depth = 0i32;
    let mut paren_depth = 0i32;
    let mut brace_depth = 0i32;
    let mut in_string = false;
    let mut escape = false;
    let mut in_item = false;
    let mut count = 0usize;

    for &b in bytes[i..].iter() {
        if in_string {
            if escape {
                escape = false;
                continue;
            }

            if b == b'\\' {
                escape = true;
                continue;
            }

            if b == b'"' {
                in_string = false;
            }

            continue;
        }

        match b {
            b'"' => {
                if bracket_depth == 1 && !in_item && brace_depth == 0 && paren_depth == 0 {
                    in_item = true;
                }
                in_string = true;
            }
            b'[' => {
                if bracket_depth == 1 && !in_item && brace_depth == 0 && paren_depth == 0 {
                    in_item = true;
                }
                bracket_depth += 1;
                if bracket_depth == 1 {
                    in_item = false;
                }
            }
            b']' => {
                if bracket_depth == 1 && in_item {
                    count += 1;
                    in_item = false;
                }
                bracket_depth -= 1;
                if bracket_depth <= 0 {
                    break;
                }
            }
            b'{' => {
                if bracket_depth == 1 && !in_item && brace_depth == 0 && paren_depth == 0 {
                    in_item = true;
                }
                brace_depth += 1
            }
            b'}' => brace_depth -= 1,
            b'(' => {
                if bracket_depth == 1 && !in_item && brace_depth == 0 && paren_depth == 0 {
                    in_item = true;
                }
                paren_depth += 1
            }
            b')' => paren_depth -= 1,
            b',' => {
                if bracket_depth == 1 && brace_depth == 0 && paren_depth == 0 && in_item {
                    count += 1;
                    in_item = false;
                }
            }
            b if b.is_ascii_whitespace() => {}
            _ => {
                if bracket_depth == 1 && !in_item {
                    in_item = true;
                }
            }
        }
    }

    Some(count)
}

#[cfg(test)]
mod tests {
    use super::{max_dollar_placeholder, shift_dollar_placeholders};

    #[test]
    fn shifts_only_numeric_dollar_placeholders() {
        let sql = "SELECT $1, $12, '$tag$', col FROM logs WHERE value = $2";
        let shifted = shift_dollar_placeholders(sql, 7);

        assert_eq!(
            shifted,
            "SELECT $8, $19, '$tag$', col FROM logs WHERE value = $9"
        );
        assert_eq!(max_dollar_placeholder(&shifted), 19);
    }

    #[test]
    fn ignores_placeholder_text_inside_sql_literals_identifiers_and_comments() {
        let sql = concat!(
            "SELECT '$1', \"$2\", $$ $3 $$, $body$ $4 $body$, $1 ",
            "-- $5\n, $2 /* $6 /* $7 */ $8 */"
        );
        let shifted = shift_dollar_placeholders(sql, 10);

        assert!(shifted.contains("'$1', \"$2\", $$ $3 $$, $body$ $4 $body$, $11"));
        assert!(shifted.contains("-- $5\n, $12 /* $6 /* $7 */ $8 */"));
        assert_eq!(max_dollar_placeholder(sql), 2);
        assert_eq!(max_dollar_placeholder(&shifted), 12);
    }

    #[test]
    fn ordinary_backslash_literal_does_not_hide_following_placeholder() {
        let sql = r#"SELECT value LIKE $1 ESCAPE '\' AND x = $3"#;
        let shifted = shift_dollar_placeholders(sql, 4);

        assert_eq!(shifted, r#"SELECT value LIKE $5 ESCAPE '\' AND x = $7"#);
        assert_eq!(max_dollar_placeholder(sql), 3);
    }

    #[test]
    fn zero_offset_keeps_placeholders_unchanged() {
        let sql = "SELECT * FROM logs WHERE value = $1";
        assert_eq!(shift_dollar_placeholders(sql, 0), sql);
    }
}
